	"encoding/json"
	"io"
	"log"
	"strings"

	"github.com/psampaz/go-mod-outdated/internal/mod"
)

func Run(r io.Reader, w io.Writer, direct bool, update bool, ci bool, style string) int {
	decoder := json.NewDecoder(r)
	var modules []*mod.Module
	for {
		var m mod.Module
		err := decoder.Decode(&m)
		if err == io.EOF {
			break
		}
		if err != nil {
			log.Println(err)
			return 0
		}
		modules = append(modules, &m)
	}

	var filtered []*mod.Module
	for _, m := range modules {
		if m.Main {
			continue
		}
		if direct && m.Indirect {
			continue
		}
		if update && m.Update == nil {
			continue
		}
		filtered = append(filtered, m)
	}

	if len(filtered) == 0 {
		return 0
	}

	hasOutdated := false
	for _, m := range filtered {
		if m.Update != nil && m.Replace == nil {
			hasOutdated = true
			break
		}
	}

	renderTable(w, filtered, style)

	if ci && hasOutdated {
		return 1
	}
	return 0
}

func renderTable(w io.Writer, modules []*mod.Module, style string) {
	headers := []string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}
	widths := make([]int, len(headers))
	for i, h := range headers {
		widths[i] = len(h)
	}

	type row struct {
		mod    string
		ver    string
		newVer string
		direct string
		valid  string
	}

	rows := make([]row, len(modules))
	for i, m := range modules {
		ver := m.Version
		if m.Replace != nil {
			ver = m.Replace.Version
		}
		newVer := ""
		if m.Replace == nil && m.Update != nil {
			newVer = m.Update.Version
		}
		directStr := "true"
		if m.Indirect {
			directStr = "false"
		}
		validStr := "true"
		if m.InvalidTimestamp() {
			validStr = "false"
		}
		rows[i] = row{mod: m.Path, ver: ver, newVer: newVer, direct: directStr, valid: validStr}
		candidates := []string{rows[i].mod, rows[i].ver, rows[i].newVer, rows[i].direct, rows[i].valid}
		for j, s := range candidates {
			if len(s) > widths[j] {
				widths[j] = len(s)
			}
		}
	}

	finalWidths := make([]int, len(widths))
	for i, wd := range widths {
		finalWidths[i] = wd + 2
	}

	formatCenter := func(s string, width int) string {
		pad := width - len(s)
		left := pad / 2
		right := pad - left
		return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
	}
	formatLeft := func(s string, width int) string {
		left := 1
		right := width - len(s) - left
		if right < 0 {
			right = 0
		}
		return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
	}

	if style == "markdown" {
		var headerCells []string
		for i, h := range headers {
			headerCells = append(headerCells, formatCenter(h, finalWidths[i]))
		}
		headerLine := "|" + strings.Join(headerCells, "|") + "|"
		w.Write([]byte(headerLine + "\n"))
		var sepCells []string
		for _, wd := range finalWidths {
			sepCells = append(sepCells, strings.Repeat("-", wd))
		}
		sepLine := "|" + strings.Join(sepCells, "|") + "|"
		w.Write([]byte(sepLine + "\n"))
		for _, r := range rows {
			var cells []string
			cells = append(cells, formatLeft(r.mod, finalWidths[0]))
			cells = append(cells, formatLeft(r.ver, finalWidths[1]))
			cells = append(cells, formatLeft(r.newVer, finalWidths[2]))
			cells = append(cells, formatLeft(r.direct, finalWidths[3]))
			cells = append(cells, formatLeft(r.valid, finalWidths[4]))
			line := "|" + strings.Join(cells, "|") + "|"
			w.Write([]byte(line + "\n"))
		}
	} else {
		border := "+"
		for _, wd := range finalWidths {
			border += strings.Repeat("-", wd) + "+"
		}
		w.Write([]byte(border + "\n"))
		var headerCells []string
		for i, h := range headers {
			headerCells = append(headerCells, formatCenter(h, finalWidths[i]))
		}
		headerLine := "|" + strings.Join(headerCells, "|") + "|"
		w.Write([]byte(headerLine + "\n"))
		w.Write([]byte(border + "\n"))
		for _, r := range rows {
			var cells []string
			cells = append(cells, formatLeft(r.mod, finalWidths[0]))
			cells = append(cells, formatLeft(r.ver, finalWidths[1]))
			cells = append(cells, formatLeft(r.newVer, finalWidths[2]))
			cells = append(cells, formatLeft(r.direct, finalWidths[3]))
			cells = append(cells, formatLeft(r.valid, finalWidths[4]))
			line := "|" + strings.Join(cells, "|") + "|"
			w.Write([]byte(line + "\n"))
		}
		w.Write([]byte(border + "\n"))
	}
}
