		ver := m.Version
		if m.Replace != nil {
			ver = m.Replace.Version
		}
		newVer := ""
		if m.Replace == nil && m.Update != nil {
			newVer = m.Update.Version
		}
		directStr := "true"
		if m.Indirect {
			directStr = "false"
		}
		validStr := "true"
//line /workspace/internal/runner/runner.go:85
